insert into public.emotion_families (emotion_family_id, family_code, family_name_vn, family_name_en, color_hex, active, sort_order)
values
('EFAM_001', 'Joy_Play', 'Niềm vui & vui chơi', 'Joy & Play', '#FFB703', true, 1),
('EFAM_002', 'Calm_Peace', 'Bình yên & thư thái', 'Calm & Peace', '#00BFA6', true, 2),
('EFAM_003', 'Love_Belonging', 'Yêu thương & gắn kết', 'Love & Connection', '#FF3D71', true, 3),
('EFAM_004', 'Interest_Growth', 'Hứng thú & mở ra', 'Interest & Openness', '#00A8E8', true, 4),
('EFAM_005', 'Uneasy_Ambivalent', 'Lấn cấn & mâu thuẫn', 'Unease & Ambivalence', '#9B5DE5', true, 5),
('EFAM_006', 'Anxiety_Stress', 'Lo âu & căng thẳng', 'Anxiety & Stress', '#F77F00', true, 6),
('EFAM_007', 'Anger_Boundary', 'Bực bội & tức giận', 'Frustration & Anger', '#E63946', true, 7),
('EFAM_008', 'Sadness_Loss', 'Buồn & mất mát', 'Sadness & Loss', '#4361EE', true, 8),
('EFAM_009', 'Shame_SelfConscious', 'Xấu hổ & tội lỗi', 'Shame & Guilt', '#8E44AD', true, 9),
('EFAM_010', 'LowEnergy_Disconnection', 'Chán nản & xa cách', 'Discouragement & Disconnection', '#64748B', true, 10),
('EFAM_011', 'Courage_Authenticity', 'Can đảm & chân thật', 'Courage & Authenticity', '#06D6A0', true, 11)
insert into public.emotions (emotion_id, emotion_family_id, emotion_name_vn, emotion_name_en, emoji, color_hex, description_vn, description_en, active, sort_order)
values
('EMO_001', 'EFAM_001', 'Vui vẻ', 'Cheerful', '😁', '#FFE066', 'Mình cảm thấy sáng   sủa, dễ chịu và có thể tận hưởng điều đang diễn ra mà không cần một lý do quá   lớn. Niềm vui này thường vừa phải, gần gũi và khiến mình muốn mỉm cười, chia   sẻ hoặc ở lại lâu hơn với khoảnh khắc hiện tại.', 'I feel bright,   pleasantly uplifted, and able to enjoy what is happening without needing a   major reason. This is an everyday kind of joy that may make me smile, share   the moment, or simply stay with it a little longer.', true, 1),
('EMO_002', 'EFAM_001', 'Hân hoan', 'Elated', '🤩', '#FFD43B', 'Một niềm vui mạnh   đang lan rộng trong mình vì điều gì đó thật sự tốt đẹp vừa xảy ra, được nhận   ra hoặc trở thành sự thật. Mình có thể cảm thấy được nâng lên, muốn reo vui,   ăn mừng hoặc chia sẻ niềm vui ấy với người khác.', 'An intense joy   spreads through me because something deeply welcome has happened, been   realized, or become true. I may feel lifted and moved to celebrate, exclaim,   or share the joy with others.', true, 2),
('EMO_003', 'EFAM_001', 'Phấn khích', 'Excited', '🎉', '#FF9F1C', 'Năng lượng trong mình   đang tăng lên trước một điều hấp dẫn, mới mẻ hoặc rất được mong đợi. Sự chú ý   hướng về phía trước và mình muốn tiến lại gần, bắt đầu hoặc tham gia ngay vào   điều đang gọi mình.', 'My energy is rising   in anticipation of something appealing, novel, or strongly desired. My   attention moves forward, and I feel drawn to begin, approach, or take part.', true, 3),
('EMO_004', 'EFAM_001', 'Thích thú', 'Delighted', '😺', '#F6BD60', 'Mình vui vì vừa gặp   một điều đáng yêu, hay ho, duyên dáng hoặc thú vị hơn mong đợi. Niềm vui có   một đối tượng khá rõ, khiến mình muốn nhìn kỹ hơn, khám phá thêm hoặc tận   hưởng thêm một chút.', 'I feel a focused   pleasure in response to something charming, clever, pleasing, or more   enjoyable than expected. It captures my attention and makes me want to   linger, explore, or enjoy it further.', true, 4),
('EMO_005', 'EFAM_001', 'Thấy buồn cười', 'Amused', '😂', '#FFB703', 'Một điều gì đó vừa   chạm đúng phần hài hước trong mình, khiến mình muốn mỉm cười hoặc bật cười.   Cảm giác này thường đến từ sự bất ngờ, lệch nhịp hoặc ngộ nghĩnh theo một   cách vô hại và dễ chịu.', 'Something has struck   me as funny, playful, or harmlessly unexpected, bringing an impulse to smile   or laugh. Amusement is usually a receptive response to humor rather than an   urge to create the play myself.', true, 5),
('EMO_006', 'EFAM_001', 'Tinh nghịch', 'Playful', '😜', '#FB8500', 'Một phần trong mình   muốn đùa, nghịch, trêu nhẹ hoặc thử điều gì đó không quá nghiêm túc. Mình   đang tìm sự tự do, ngẫu hứng và niềm vui trong chính cách tương tác, chứ   không nhất thiết cần đạt một kết quả nào.', 'A lively part of me   wants to joke, tease gently, experiment, or step outside seriousness. The   pleasure lies in spontaneity and playful interaction rather than in achieving   a particular outcome.', true, 6),
('EMO_007', 'EFAM_002', 'Bình yên', 'Peaceful', '🕊️', '#52B788', 'Bên trong mình đang   tương đối yên, không có điều gì kéo, thúc hoặc đe dọa quá mạnh. Mình vẫn tỉnh   táo và có mặt, nhưng không cần liên tục phòng thủ, phản ứng hay giải quyết   điều gì ngay lúc này.', 'I feel an inner quiet   in which nothing is strongly pulling, pressuring, or threatening me. I remain   aware and present without needing to defend myself, react, or solve something   immediately.', true, 7),
('EMO_008', 'EFAM_002', 'Thư thái / Thảnh thơi', 'Relaxed / At ease', '🛋️', '#B7E4C7', 'Cơ thể và đầu óc đã   bớt giữ lực, đồng thời mình cũng tạm rời khỏi cảm giác phải làm, phải gồng   hoặc phải theo kịp. Hơi thở, chuyển động và sự chú ý trở nên tự nhiên hơn,   như thể mình được phép nghỉ trong chính khoảnh khắc này.', 'My body and mind are   releasing tension, and I feel temporarily free from the pressure to perform,   keep up, or hold everything together. Breathing, movement, and attention   become easier, as though I am allowed to rest within the moment.', true, 8),
('EMO_009', 'EFAM_002', 'Nhẹ nhõm', 'Relieved', '😮‍💨', '#95D5B2', 'Một mối lo, áp lực   hoặc nguy cơ vừa giảm xuống, đi qua hoặc hóa ra không nghiêm trọng như mình   sợ. Cảm giác rõ nhất là trước đó mình đã phải căng lên, còn bây giờ thì có   thể thở ra và buông bớt.', 'A worry, pressure, or   threat has eased, passed, or proved less serious than I feared. The contrast   is clear: I had been bracing myself, and now I can exhale and let some of   that tension go.', true, 9),
('EMO_010', 'EFAM_002', 'Hài lòng', 'Content', '😊', '#A7C957', 'Mình cảm thấy điều   đang có là đủ hoặc đang nằm ở một chỗ khá phù hợp với mình. Không nhất thiết   có niềm vui lớn; chỉ là mình không bị thôi thúc phải có thêm, sửa ngay hoặc   làm cho khoảnh khắc này trở thành một điều khác.', 'What is present feels   sufficient or fitting for me right now. I do not need intense joy; I simply   do not feel an urgent need for more, for immediate change, or for the moment   to become something else.', true, 10),
('EMO_011', 'EFAM_002', 'An tâm', 'Reassured', '🛡️', '#55A630', 'Điều từng khiến mình   lo hoặc chưa chắc chắn đã có thêm thông tin, sự xác nhận hoặc điểm tựa để dịu   xuống. Mình chưa cần biết mọi thứ sẽ hoàn hảo, nhưng đã có đủ cơ sở để bớt   cảnh giác và tin rằng mình có thể ổn.', 'Something that had   worried or unsettled me now feels more manageable because I have gained   information, reassurance, or support. I do not need certainty that everything   will be perfect; I have enough to lower my guard and trust that I can be   okay.', true, 11),
('EMO_012', 'EFAM_002', 'Vững vàng', 'Grounded', '🪵', '#40916C', 'Mình cảm thấy có nền,   có điểm tựa và không dễ bị hoàn cảnh kéo đi khỏi chính mình. Dù mọi thứ chưa   hẳn yên, mình vẫn cảm nhận được mình đang đứng ở đâu, điều gì quan trọng và   mình có thể giữ nhịp thế nào.', 'I feel anchored,   supported, and less likely to be swept away by circumstances. Even if the   situation is not fully calm, I can sense where I stand, what matters, and how   to keep my footing.', true, 12),
('EMO_013', 'EFAM_003', 'Yêu thương', 'Loving', '❤️', '#FF4D6D', 'Một tình cảm ấm áp   đang hướng từ mình về một người, một sự sống hoặc một phần của chính mình.   Mình muốn đến gần, quan tâm, gìn giữ và mong điều tốt cho đối tượng ấy, không   chỉ vì họ hữu ích hay đáp ứng điều gì cho mình.', 'A warm affection is   moving from me toward another person, a living being, or a part of myself. I   want to come closer, care, protect, and wish them well beyond what they can   do for me.', true, 13),
('EMO_014', 'EFAM_003', 'Được thương', 'Feeling loved', '🥰', '#FF8FAB', 'Mình cảm nhận được sự   quan tâm, dịu dàng và thiện ý thật sự đang hướng về mình. Không chỉ biết bằng   lý trí rằng ai đó quan tâm, mình còn cảm thấy mình đang được trân trọng, được   giữ trong lòng và không phải tự mình gánh mọi thứ.', 'I can feel genuine   care, tenderness, and goodwill being directed toward me. It is more than   knowing intellectually that someone cares; I feel valued, emotionally held,   and less alone with what I carry.', true, 14),
('EMO_015', 'EFAM_003', 'Thân thuộc / Gần gũi', 'Familiar and close', '🤗', '#FF99AC', 'Ở bên người này, nơi   này hoặc trong mối quan hệ này, mình cảm thấy quen, dễ trở về và khoảng cách   giữa hai bên được thu ngắn. Mình không phải mất quá nhiều sức để dò xét hay   diễn giải, nên có thể hiện diện tự nhiên và chia sẻ thật hơn.', 'With this person,   place, or relationship, I feel a sense of familiarity and reduced emotional   distance. I do not have to spend as much energy scanning or translating   myself, so I can be more natural and genuinely connected.', true, 15),
('EMO_016', 'EFAM_003', 'Cảm thấy thuộc về', 'Belonging', '🫂', '#E76F91', 'Mình cảm thấy mình có   một vị trí hợp lệ trong mối quan hệ, nhóm hoặc cộng đồng này. Mình được tính   là một phần của “chúng ta” mà không phải liên tục chứng minh mình xứng đáng   hoặc xóa bỏ quá nhiều khác biệt để được ở lại.', 'I feel that I have a   legitimate place in this relationship, group, or community. I am part of a   meaningful “we” without constantly proving that I deserve to stay or erasing   too much of who I am.', true, 16),
('EMO_017', 'EFAM_003', 'Cảm thấy được thấu   hiểu', 'Feeling understood', '👀', '#E5989B', 'Mình cảm thấy một   người đã nhận ra khá đúng điều mình đang trải qua, kể cả phần ý nghĩa nằm sau   lời nói hoặc hành vi bên ngoài. Họ không nhất thiết phải đồng ý, nhưng mình   không còn cảm giác phải một mình cố giải thích mình là ai và chuyện này có ý   nghĩa gì.', 'I feel that another   person has accurately recognized what I am going through, including some of   the meaning beneath my words or behavior. They do not have to agree, but I no   longer feel alone in trying to explain myself and the significance of the   experience.', true, 17),
('EMO_018', 'EFAM_003', 'Biết ơn', 'Grateful', '🙏', '#F4978E', 'Mình nhận ra một điều   tốt đẹp đã được trao, được nhận hoặc đang hiện diện trong đời mình, và điều   ấy không còn bị xem là hiển nhiên. Sự chú ý của mình tự nhiên hướng về người,   cơ hội hoặc khoảnh khắc đã mang điều tốt ấy đến.', 'I recognize something   good that has been given, received, or is present in my life, and I no longer   take it for granted. My attention naturally turns toward the person,   opportunity, or moment that made the good possible.', true, 18),
('EMO_019', 'EFAM_003', 'Trìu mến', 'Tender', '🌷', '#FFB4C8', 'Lòng mình mềm lại   trước một người, một sự sống hoặc một phần rất mong manh và đáng quý. Mình   muốn đến gần theo cách nhẹ nhàng hơn, nâng niu hơn và cẩn thận để điều ấy   không bị tổn thương.', 'My heart softens   toward someone or something precious and vulnerable. I feel drawn to approach   gently, cherish it, and take care not to cause harm.', true, 19),
('EMO_020', 'EFAM_003', 'Trắc ẩn', 'Compassionate', '💞', '#FF7FA3', 'Mình nhận ra nỗi khó   của người khác hoặc của chính mình và cảm thấy muốn đáp lại bằng sự chăm sóc   phù hợp. Cảm xúc này có thể chứa cả nỗi buồn lẫn sự ấm áp, nhưng vẫn giữ phẩm   giá và sự ngang hàng của người đang đau.', 'I recognize another   person''s—or my own—suffering and feel moved to respond with appropriate care.   Compassion can hold both sadness and warmth while preserving the dignity and   equality of the person who is hurting.', true, 20),
('EMO_021', 'EFAM_003', 'Thương mình', 'Self-compassion', '🤲', '#FF8FAB', 'Mình đang nhìn phần   khó khăn, vụng về hoặc chưa hoàn hảo của bản thân bằng sự tử tế thay vì trừng   phạt. Mình vẫn có thể nhận trách nhiệm và muốn thay đổi, nhưng không cần hạ   nhục hay bỏ rơi chính mình để làm điều đó.', 'I am relating to my   own pain, mistakes, or imperfections with kindness rather than punishment. I   can still take responsibility and want to change without humiliating or   abandoning myself in the process.', true, 21),
('EMO_022', 'EFAM_004', 'Tò mò', 'Curious', '🧐', '#35B9E9', 'Mình nhận ra có một   điều chưa biết, chưa hiểu hoặc chưa khám phá hết, và khoảng trống ấy khiến   mình muốn tiến lại gần. Tò mò thường mang theo một câu hỏi, dù mình chưa diễn   đạt được thành lời hay chưa biết câu trả lời sẽ dẫn mình tới đâu.', 'I notice a gap in   what I know or understand, and that gap draws me closer. Curiosity usually   carries a question, even when I cannot yet put it into words or know where   the answer may lead.', true, 22),
('EMO_023', 'EFAM_004', 'Hứng thú', 'Interested', '✨', '#00B4D8', 'Một người, ý tưởng,   hoạt động hoặc chủ đề đang tự nhiên kéo và giữ sự chú ý của mình. Mình muốn ở   lại, tìm hiểu hoặc tham gia thêm vì điều ấy có sức hấp dẫn hoặc có liên quan   đến phần nào đó trong mình.', 'A person, idea,   activity, or subject naturally draws and holds my attention. I want to stay   with it, learn more, or participate because it feels appealing or personally   relevant.', true, 23),
('EMO_024', 'EFAM_004', 'Có cảm hứng', 'Inspired', '💡', '#48CAE4', 'Một điều mình vừa gặp   đã mở ra cách nhìn, khả năng hoặc hình ảnh về cuộc sống mà trước đó mình chưa   thấy rõ. Mình không chỉ thấy thích; mình còn cảm thấy được nâng lên và muốn   tạo ra, thay đổi hoặc sống gần hơn với điều vừa chạm tới mình.', 'Something I   encountered has opened a perspective, possibility, or way of living that I   could not previously see as clearly. I do not merely enjoy it; I feel lifted   and moved to create, change, or live closer to what has touched me.', true, 24),
('EMO_025', 'EFAM_004', 'Hy vọng', 'Hopeful', '🌤️', '#90E0EF', 'Mình đang hướng về   một kết quả mình mong muốn và vẫn cảm thấy nó có thể xảy ra, dù hiện tại chưa   chắc chắn hoặc còn nhiều khó khăn. Hy vọng không phủ nhận thực tế; nó giữ cho   tương lai chưa hoàn toàn đóng lại.', 'I am oriented toward   a desired outcome and still sense that it may be possible, even though   uncertainty or difficulty remains. Hope does not deny reality; it keeps the   future from feeling completely closed.', true, 25),
('EMO_026', 'EFAM_004', 'Có động lực', 'Motivated', '🚀', '#0096C7', 'Mình cảm thấy có lý   do và có đủ năng lượng để bắt đầu hoặc tiếp tục một việc. Điều mình muốn làm   không chỉ tồn tại như ý nghĩ; nó đang tạo lực kéo để mình tiến về phía trước   và biến ý định thành hành động.', 'I feel that I have   both a reason and enough energy to begin or continue. What I want to do is no   longer only an idea; it is generating momentum that can turn intention into   action.', true, 26),
('EMO_027', 'EFAM_004', 'Sáng tỏ / Rõ ràng', 'Clear / Clarity', '🔦', '#0077B6', 'Một mối liên hệ, lựa   chọn hoặc điều quan trọng vừa trở nên dễ nhìn và dễ hiểu hơn trong mình. Mình   không nhất thiết đã giải quyết xong mọi thứ, nhưng đã biết mình đang đối diện   với điều gì và bước tiếp theo có thể nằm ở đâu.', 'A connection, choice,   or important truth has become easier for me to see and understand. I may not   have solved everything, but I have a clearer sense of what I am facing and   where the next step may be.', true, 27),
('EMO_028', 'EFAM_004', 'Sẵn sàng', 'Ready', '🚪', '#0EAD69', 'Mình cảm thấy đã có   đủ nguồn lực, đủ hiểu biết hoặc đủ chấp nhận để bước vào điều tiếp theo. Sẵn   sàng không có nghĩa là không còn sợ hay không còn thiếu sót; chỉ là mình   không muốn tiếp tục đứng ngoài ngưỡng cửa nữa.', 'I feel that I have   enough resources, understanding, or acceptance to move into what comes next.   Readiness does not mean that fear or uncertainty has disappeared; it means I   no longer want to remain outside the threshold.', true, 28),
('EMO_029', 'EFAM_005', 'Lấn cấn', 'Uneasy', '🌫️', '#9B8AFB', 'Mình cảm thấy có gì   đó chưa ổn, chưa đúng hoặc chưa trọn, nhưng chưa xác định rõ vấn đề nằm ở   đâu. Nó giống một gợn nhỏ còn ở lại, khiến mình chưa thể hoàn toàn yên lòng   dù chưa có một nguy cơ cụ thể.', 'I sense that   something is not quite right, settled, or complete, but I cannot yet identify   exactly what the issue is. It feels like a small inner disturbance that   prevents me from fully relaxing, even without a specific threat.', true, 29),
('EMO_030', 'EFAM_005', 'Mơ hồ', 'Unclear', '🌁', '#8A7CCF', 'Điều đang xảy ra, ý   nghĩa của nó hoặc cảm xúc bên trong mình chưa có hình dạng đủ rõ. Mình có một   số mảnh thông tin, nhưng chúng còn loãng hoặc thiếu nét nên chưa thể tạo   thành một cách hiểu vững.', 'What is happening,   what it means, or what I feel has not yet taken a clear shape. I have some   pieces of information, but they remain diffuse or incomplete and do not yet   form a stable understanding.', true, 30),
('EMO_031', 'EFAM_005', 'Mâu thuẫn', 'Ambivalent', '🌓', '#7B61FF', 'Hai cảm xúc, mong   muốn hoặc giá trị trái chiều đang cùng có mặt trong mình. Một phần muốn tiến   lại gần trong khi phần khác muốn lùi ra; cả hai phía đều có thể thật và đều   cần được lắng nghe.', 'Two opposing   feelings, desires, or values are present in me at the same time. One part may   want to move closer while another pulls away, and both sides may be real and   worthy of attention.', true, 31),
('EMO_032', 'EFAM_005', 'Bâng khuâng', 'Wistful', '☁️', '#A78BFA', 'Một cảm giác nhẹ, xa   xăm và hơi se lòng đang giữ mình lại bên một người, ký ức, khả năng hoặc điều   đang đổi thay. Mình không hẳn buồn, cũng không hoàn toàn vui; mình chỉ muốn ở   lại với nó thêm một chút mà chưa cần kết luận.', 'A soft, distant,   slightly aching feeling keeps me close to a person, memory, possibility, or   something that is changing. I am not entirely sad or happy; I simply want to   linger without forcing a conclusion.', true, 32),
('EMO_033', 'EFAM_005', 'Ngọt ngào xen buồn', 'Bittersweet', '🥲', '#B197FC', 'Niềm vui và nỗi buồn   cùng xuất hiện vì chính một điều: nó đẹp và đáng quý, nhưng cũng đang kết   thúc, đổi thay hoặc không thể giữ mãi. Hai sắc thái không triệt tiêu nhau;   chúng cùng làm trải nghiệm trở nên đầy hơn.', 'Joy and sadness arise   together in response to the same experience: it is beautiful and precious,   yet it is ending, changing, or cannot be kept forever. Neither feeling   cancels the other; together they make the experience feel fuller.', true, 33),
('EMO_034', 'EFAM_005', 'Chênh vênh', 'Unsteady', '🪶', '#8E7DF2', 'Mình cảm thấy thiếu   một điểm tựa rõ, chưa biết mình đang đứng ở đâu hoặc điều gì có thể giữ mình   lại. Không nhất thiết có nguy hiểm trước mắt, nhưng nền bên dưới chưa đủ chắc   để mình hoàn toàn yên tâm.', 'I feel that I lack a   reliable point of support and am unsure where I stand or what can hold me.   There may be no immediate danger, but the ground beneath the situation does   not yet feel steady enough.', true, 34),
('EMO_035', 'EFAM_005', 'Phân vân', 'Undecided', '↔️', '#7C6FF6', 'Mình đang nhìn thấy   nhiều lựa chọn hoặc nhiều cách hiểu đều có lý, nên sự chú ý cứ đi qua đi lại   giữa chúng. Vấn đề không hẳn là mình sợ hành động, mà là mình chưa biết   phương án nào phù hợp hơn để chọn.', 'I can see several   options or interpretations that each make sense, so my attention keeps moving   between them. The difficulty is not necessarily fear of acting; I do not yet   know which option fits best.', true, 35),
('EMO_036', 'EFAM_005', 'Do dự', 'Hesitant', '❓', '#A29BFE', 'Mình đang đứng gần   một lựa chọn hoặc hành động, nhưng một phần vẫn giữ lại vì chưa đủ chắc chắn,   an toàn hoặc sẵn sàng. Khác với phân vân giữa nhiều phương án, do dự có thể   xảy ra ngay cả khi mình đã biết mình muốn làm gì.', 'I am close to making   a choice or taking action, but part of me still holds back because I do not   feel certain, safe, or ready enough. Unlike indecision between several   options, hesitation can remain even when I already know what I want to do.', true, 36),
('EMO_037', 'EFAM_005', 'Bối rối', 'Confused', '😵‍💫', '#A66CFF', 'Các thông tin, tín   hiệu hoặc kỳ vọng trong tình huống chưa khớp với nhau, khiến mình không biết   nên hiểu điều gì theo cách nào. Mình có thể thấy đầu óc xoay vòng vì càng cố   ghép các mảnh lại, chúng càng chưa thành một bức tranh hợp lý.', 'The information,   signals, or expectations in the situation do not fit together, leaving me   unsure how to interpret what is happening. My mind may spin as I try to   assemble pieces that still do not form a coherent picture.', true, 37),
('EMO_038', 'EFAM_006', 'Lo lắng', 'Worried', '😟', '#FF9F43', 'Tâm trí mình đang   hướng về những điều không mong muốn có thể xảy ra và cố dự đoán, chuẩn bị   hoặc ngăn chúng lại. Mình thường biết tương đối rõ mình đang lo về việc gì,   dù chưa biết khả năng nó xảy ra đến đâu.', 'My mind is focused on   unwanted possibilities and keeps trying to predict, prepare for, or prevent   them. I usually know what I am worried about, even when the actual likelihood   remains uncertain.', true, 38),
('EMO_039', 'EFAM_006', 'Bất an', 'Anxious', '🫨', '#F8961E', 'Mình thấy không yên   và khó thả lỏng, đôi khi dù chưa chỉ ra được một nguy cơ cụ thể. Cảm giác như   có điều gì đó chưa đủ an toàn hoặc chưa thể tin cậy, khiến mình tiếp tục quan   sát và đề phòng.', 'I feel unsettled and   unable to fully relax, sometimes without a clearly identifiable threat.   Something feels unsafe or unreliable enough to keep me watchful and guarded.', true, 39),
('EMO_040', 'EFAM_006', 'Hồi hộp', 'Nervous', '🫀', '#F9844A', 'Năng lượng trong mình   tăng lên trước một sự kiện sắp xảy ra. Một phần muốn tiến tới, nhưng phần   khác lo mình có thể không làm tốt, không được đón nhận hoặc không kiểm soát   được kết quả.', 'My energy rises   before an upcoming event. Part of me wants to move toward it, while another   part worries about performance, acceptance, or what may happen.', true, 40),
('EMO_041', 'EFAM_006', 'Sợ hãi', 'Afraid', '😨', '#FF6B35', 'Mình cảm nhận một mối   đe dọa tương đối rõ và muốn tránh, chạy khỏi, chống lại hoặc tìm nơi an toàn.   Nguy cơ có cảm giác gần và thật đủ để cơ thể lẫn sự chú ý đều ưu tiên việc tự   bảo vệ.', 'I perceive a   relatively clear threat and feel an urge to avoid, escape, resist, or seek   safety. The danger feels immediate enough for both my body and attention to   prioritize protection.', true, 41),
('EMO_042', 'EFAM_006', 'Sợ điều sắp đến', 'Dread', '🌑', '#D97706', 'Một nỗi sợ nặng đang   phủ lên điều mình biết hoặc tin rằng sắp phải đối diện. Chỉ nghĩ đến nó cũng   khiến mình muốn trì hoãn, tránh né hoặc ước rằng khoảng thời gian phía trước   đừng đến.', 'A heavy fear hangs   over something I expect to face. Even thinking about it may make me want to   delay, avoid, or wish that the approaching moment would not arrive.', true, 42),
('EMO_043', 'EFAM_006', 'Hoảng hốt', 'Alarmed', '🚨', '#E85D04', 'Sợ hãi bật lên mạnh   và đột ngột khi một điều xảy ra nhanh hơn khả năng chuẩn bị của mình. Mình   vẫn còn nhận biết khá rõ tác nhân vừa khiến mình giật mình và đang khẩn   trương tìm cách phản ứng hoặc trở lại an toàn.', 'Fear surges suddenly   when something happens faster than I can prepare for. I can still identify   the immediate trigger and urgently try to respond or return to safety.', true, 43),
('EMO_044', 'EFAM_006', 'Hoảng loạn', 'Panicked', '🆘', '#EF4444', 'Nỗi sợ tăng quá nhanh   và quá mạnh, khiến mình khó suy nghĩ rõ, khó định hướng hoặc cảm thấy phải   thoát khỏi tình huống ngay lập tức. Khác với hoảng hốt, mức kích hoạt lúc này   có thể làm mình mất phần lớn cảm giác kiểm soát.', 'Fear escalates so   rapidly and intensely that I struggle to think clearly, orient myself, or   remain where I am. Unlike alarm, panic can significantly disrupt my sense of   control and create an urgent need to escape.', true, 44),
('EMO_045', 'EFAM_006', 'Áp lực', 'Pressured', '🧱', '#F3722C', 'Mình cảm thấy nhiều   kỳ vọng, trách nhiệm hoặc thời hạn đang đè lên khả năng hiện tại. Có cảm giác   mình phải đáp ứng, phải làm nhanh hơn hoặc không được phép thất bại, dù nguồn   lực bên trong đang không theo kịp.', 'I feel that   expectations, responsibilities, or deadlines are pressing against my current   capacity. I may feel that I must perform, move faster, or avoid failure even   when my internal resources cannot keep pace.', true, 45),
('EMO_046', 'EFAM_006', 'Quá tải', 'Overwhelmed', '🌪️', '#F94144', 'Có quá nhiều thông   tin, nhiệm vụ, kích thích hoặc cảm xúc cùng lúc để mình xử lý một cách có   trật tự. Mình không chỉ bận; mình cảm thấy khả năng tiếp nhận đã gần đầy và   thêm một điều nhỏ cũng có thể trở thành quá nhiều.', 'There is more   information, responsibility, stimulation, or emotion than I can organize and   process at once. I am not merely busy; my capacity feels nearly full, and   even one more small demand may become too much.', true, 46),
('EMO_047', 'EFAM_006', 'Căng thẳng', 'Stressed', '🪢', '#FF7F50', 'Cơ thể và tâm trí   mình đang giữ chặt để đáp ứng, kiểm soát hoặc phòng vệ trước điều đang diễn   ra. Mình có thể vẫn hoạt động được, nhưng phải tiêu tốn nhiều sức để duy trì   sự tập trung và không để mọi thứ vượt khỏi tầm tay.', 'My body and mind are   tightening in order to cope, control, or defend against what is happening. I   may still be functioning, but it takes significant effort to stay focused and   keep things from slipping beyond my control.', true, 47),
('EMO_048', 'EFAM_006', 'Bồn chồn', 'Restless', '🌀', '#F9C74F', 'Năng lượng trong mình   không tìm được chỗ yên, khiến mình khó ngồi lại hoặc liên tục muốn làm, đổi   tư thế hay kiểm tra một điều gì đó. Mình cảm thấy bị thúc từ bên trong nhưng   chưa chắc biết hành động nào thật sự sẽ giúp.', 'My energy cannot   settle, making it difficult to stay still and creating repeated urges to   move, act, shift position, or check something. I feel internally driven   without necessarily knowing what action would actually help.', true, 48),
('EMO_049', 'EFAM_006', 'Nôn nóng', 'Impatient', '😒', '#F59E0B', 'Mình muốn một điều   diễn ra nhanh hơn và đang thấy khoảng chờ, tốc độ hoặc sự chậm trễ trở nên   khó chịu. Sự chú ý bị kéo về phía kết quả đến mức mình khó ở lại với nhịp   hiện tại.', 'I want something to   happen sooner, and the waiting, pace, or delay feels increasingly difficult.   My attention is pulled so strongly toward the outcome that it becomes hard to   remain with the present rhythm.', true, 49),
('EMO_050', 'EFAM_006', 'Bất lực', 'Helpless', '🆘', '#F6AD55', 'Mình muốn thay đổi,   ngăn lại hoặc bảo vệ một điều quan trọng nhưng hiện chưa nhìn thấy khả năng,   quyền lực hay nguồn lực để làm được. Điều đau nhất không chỉ là tình huống   khó, mà là cảm giác mình không thể tạo ra khác biệt vào lúc này.', 'I want to change,   prevent, or protect something important, but I cannot currently see enough   ability, power, or resources to do so. The pain lies not only in the   situation itself, but in feeling unable to make a difference right now.', true, 50),
('EMO_051', 'EFAM_007', 'Cáu kỉnh', 'Irritated', '😒', '#FF7B72', 'Ngưỡng chịu đựng của   mình đang thấp, nên những âm thanh, câu nói hoặc bất tiện nhỏ cũng dễ làm   mình khó chịu. Cảm giác này thường lan tỏa và không nhất thiết bắt nguồn từ   một vi phạm lớn hay một đối tượng duy nhất.', 'My tolerance is low,   so minor noises, comments, or inconveniences easily bother me. Irritation is   often diffuse and does not require a major violation or one clear target.', true, 51),
('EMO_052', 'EFAM_007', 'Bực bội', 'Frustrated', '😤', '#FF6B6B', 'Mình muốn tiến tới   một kết quả nhưng đang bị cản, trì hoãn hoặc phải thử đi thử lại mà vẫn chưa   được. Năng lượng muốn hành động vẫn còn đó, nhưng nó đang liên tục va vào một   vật cản.', 'I am trying to reach   an outcome but feel blocked, delayed, or repeatedly unsuccessful. The energy   to act remains, but it keeps colliding with an obstacle.', true, 52),
('EMO_053', 'EFAM_007', 'Tức giận', 'Angry', '🔥', '#FF4D4F', 'Mình cảm thấy một   giới hạn, nhu cầu, giá trị hoặc điều quan trọng đã bị xem nhẹ hay xâm phạm.   Cơn giận tạo ra năng lượng để phản đối, bảo vệ, đòi thay đổi hoặc khôi phục   điều mà mình cho là đúng.', 'I feel that an   important boundary, need, value, or concern has been dismissed or violated.   Anger generates energy to protest, protect, demand change, or restore what   feels right.', true, 53),
('EMO_054', 'EFAM_007', 'Ấm ức', 'Aggrieved', '😣', '#E63946', 'Mình cảm thấy đã bị   đối xử không đúng, nhưng điều ấy chưa được nghe, chưa được hiểu hoặc mình   chưa thể nói ra đầy đủ. Cơn giận bị giữ lại bên trong nên thường pha với tủi   thân, nghẹn hoặc cảm giác mình đang phải chịu một điều không ai nhìn thấy.', 'I feel wronged, but   the experience has not been heard, understood, or fully expressed. The anger   remains held inside and may mix with hurt, constriction, or the sense of   enduring something unseen.', true, 54),
('EMO_055', 'EFAM_007', 'Bất bình', 'Indignant', '⚖️', '#D90429', 'Mình phản ứng trước   điều mà mình cho là bất công, thiếu tôn trọng hoặc đi ngược một nguyên tắc   quan trọng. Cảm giác này mang theo một nhận định rõ rằng điều đó không nên   được xem là bình thường hay dễ dàng bỏ qua.', 'I react to something   I see as unfair, disrespectful, or contrary to an important principle.   Indignation carries a clear sense that the situation should not be normalized   or casually dismissed.', true, 55),
('EMO_056', 'EFAM_007', 'Phẫn nộ', 'Outraged', '🌋', '#C1121F', 'Một cơn giận rất mạnh   đang xuất hiện trước điều mình xem là nghiêm trọng, tàn nhẫn hoặc hoàn toàn   không thể chấp nhận. Mình không chỉ muốn phản đối; mình cảm thấy một giá trị   căn bản đang bị chà đạp và cần được bảo vệ quyết liệt.', 'I feel an intense   anger toward something I regard as grave, cruel, or wholly unacceptable. I do   not merely object; I feel that a fundamental value has been violated and   demands forceful protection.', true, 56),
('EMO_057', 'EFAM_007', 'Oán giận', 'Resentful', '🌶️', '#D00000', 'Cơn giận vẫn ở lại   qua thời gian vì tổn thương chưa được thừa nhận, trách nhiệm chưa được nhận   hoặc sự việc chưa được sửa chữa. Mỗi lần nhớ lại, mình có thể cảm thấy phần   bất công ấy vẫn còn nguyên và tiếp tục chiếm chỗ trong mình.', 'Anger remains over   time because a hurt has not been acknowledged, responsibility has not been   taken, or repair has not occurred. Each reminder can make the original   unfairness feel unresolved and still present within me.', true, 57),
('EMO_058', 'EFAM_008', 'Buồn', 'Sad', '😢', '#4D96FF', 'Một điều quan trọng   đã không xảy ra như mình mong, đã rời xa hoặc không còn ở trong tầm mình giữ   được. Nỗi buồn làm nhịp bên trong chậm xuống để mình nhận ra giá trị của điều   đang thiếu, đang đổi khác hoặc đã mất.', 'Something important   has not happened as I hoped, has moved away, or can no longer be held.   Sadness slows me down so I can register the value of what is missing,   changing, or lost.', true, 58),
('EMO_059', 'EFAM_008', 'Tủi thân', 'Hurt and overlooked', '😞', '#6C8AE4', 'Mình buồn vì cảm thấy   mình không được quan tâm, nhớ tới, bảo vệ hoặc đối xử như mình từng hy vọng   từ một người quan trọng. Nỗi đau không chỉ nằm ở sự việc, mà còn ở ý nghĩa   rằng có lẽ mình không có nhiều trọng lượng với họ như mình nghĩ.', 'I feel hurt because I   was not cared for, remembered, protected, or treated as I hoped by someone   important. The pain includes what the event seems to imply about how much I   matter to them.', true, 59),
('EMO_060', 'EFAM_008', 'Cô đơn', 'Lonely', '🌌', '#577590', 'Mình đang thiếu một   sự kết nối có ý nghĩa: một người để thật sự gặp gỡ, chia sẻ hoặc cảm thấy   được ở cùng. Cô đơn vẫn có thể xuất hiện giữa nơi đông người nếu không có ai   chạm được tới phần mình đang sống bên trong.', 'I am missing   meaningful connection—someone with whom I can genuinely meet, share, or feel   accompanied. Loneliness can exist even among many people when no one reaches   the part of me that feels most alive inside.', true, 60),
('EMO_061', 'EFAM_008', 'Nhớ nhung', 'Longing', '💭', '#4895EF', 'Một người, nơi chốn,   thời điểm hoặc trải nghiệm đang được kéo trở lại trong lòng cùng mong muốn   được gần lại. Cảm giác này thường chứa cả sự ấm áp vì điều ấy từng quan trọng   và nỗi se lại vì lúc này nó đang vắng mặt.', 'A person, place,   time, or experience is being drawn back into my awareness, along with a wish   to be close to it again. Longing often holds both warmth for what mattered   and the ache of its present absence.', true, 61),
('EMO_062', 'EFAM_008', 'Thất vọng', 'Disappointed', '📉', '#457B9D', 'Điều mình kỳ vọng ở   một kết quả, một người hoặc chính mình đã không được đáp lại. Năng lượng từng   hướng tới tương lai bỗng hạ xuống vì thực tế không giống điều mình đã tin,   chuẩn bị hoặc hy vọng.', 'An expectation I held   about an outcome, another person, or myself has not been met. The energy once   directed toward the future drops as reality diverges from what I believed,   prepared for, or hoped.', true, 62),
('EMO_063', 'EFAM_008', 'Hụt hẫng', 'Let down', '🫗', '#6F8EDB', 'Một điều mình đã gần   như chờ đợi sẽ xuất hiện lại không đến, biến mất hoặc thay đổi quá đột ngột.   Cảm giác giống như chân vừa bước vào khoảng không: một sự rơi ngắn, trống và   khó kịp chuẩn bị.', 'Something I had   almost expected to be there failed to appear, disappeared, or changed too   suddenly. It feels like stepping into empty space—a brief, hollow drop that I   was not prepared for.', true, 63),
('EMO_064', 'EFAM_008', 'Vỡ mộng', 'Disillusioned', '🫥', '#4D96FF', 'Không chỉ một kết quả   làm mình thất vọng; cả niềm tin, hình ảnh đẹp hoặc câu chuyện mình từng đặt   vào một người hay một tương lai đang không còn đứng vững. Mình phải đối diện   với khoảng cách giữa điều mình từng tin và điều thực tế vừa cho thấy.', 'It is not only an   outcome that disappoints me; a larger belief, idealized image, or story I   held about a person or future no longer stands. I am confronting the gap   between what I believed and what reality has revealed.', true, 64),
('EMO_065', 'EFAM_008', 'Đau buồn vì mất mát', 'Grieving', '🕯️', '#277DA1', 'Mình đang đi qua sự   mất đi của một người, mối quan hệ, vai trò, tương lai hoặc phần đời từng có ý   nghĩa sâu sắc. Nỗi đau có thể đến thành nhiều đợt và chứa cả buồn, giận, nhớ,   trống trải hoặc khó tin rằng điều ấy thật sự đã đổi khác.', 'I am living through   the loss of a person, relationship, role, future, or meaningful part of life.   Grief may arrive in waves and contain sadness, anger, longing, emptiness, or   difficulty accepting that life has truly changed.', true, 65),
('EMO_066', 'EFAM_008', 'Tiếc nuối', 'Regretful', '🍂', '#3A86FF', 'Mình nhìn lại một lựa   chọn, cơ hội hoặc khả năng đã qua và ước rằng mọi chuyện từng có thể khác.   Cảm giác này không nhất thiết nói rằng mình đã làm điều sai; đôi khi mình chỉ   đang buồn cho một con đường không còn có thể quay lại.', 'I look back on a   choice, opportunity, or possibility and wish things could have been   different. This does not necessarily mean that I did something wrong; I may   simply be mourning a path that can no longer be taken.', true, 66),
('EMO_067', 'EFAM_008', 'Đau lòng', 'Heartbroken', '🥀', '#3B82F6', 'Một mối quan hệ hoặc   điều mình yêu quý đang gây ra nỗi đau rất gần và rõ, như thể phần mềm nhất   trong mình vừa bị chạm mạnh. Điều ấy có thể vẫn còn hiện diện trong đời mình,   nhưng sự tổn thương, xa cách hoặc mất niềm tin đang khiến lòng mình đau.', 'A relationship or   something deeply cherished is causing a vivid and intimate pain, as though a   tender part of me has been struck. The person or bond may still exist, yet   hurt, distance, or broken trust is making my heart ache.', true, 67),
('EMO_068', 'EFAM_009', 'Xấu hổ', 'Ashamed', '🙈', '#C77DFF', 'Mình không chỉ nghĩ   rằng mình đã làm sai, mà còn sợ một phần con người mình là không đủ tốt, đáng   chê hoặc không thể được chấp nhận. Mình có thể muốn che giấu, thu nhỏ hoặc   biến mất khỏi ánh nhìn của người khác.', 'I fear that not only   my action but some part of who I am is inadequate, unacceptable, or worthy of   rejection. I may want to hide, shrink, or disappear from other people''s view.', true, 68),
('EMO_069', 'EFAM_009', 'Ngượng ngùng', 'Embarrassed', '☺️', '#E0AAFF', 'Mình ý thức rõ về bản   thân sau một khoảnh khắc vụng về, bị chú ý hoặc không biết phải phản ứng thế   nào cho tự nhiên. Cảm giác này thường nhẹ và ngắn hơn xấu hổ, và mình vẫn có   thể nhìn lại nó với chút hài hước khi tình huống qua đi.', 'I become acutely   self-conscious after an awkward moment, unexpected attention, or uncertainty   about how to respond naturally. Embarrassment is usually lighter and more   temporary than shame, and I may later be able to see the moment with some   humor.', true, 69),
('EMO_070', 'EFAM_009', 'Tội lỗi', 'Guilty', '🧩', '#B565D9', 'Mình nhận ra một hành   động hoặc sự thiếu sót của mình đã đi ngược giá trị, cam kết hay gây ảnh   hưởng không mong muốn. Trọng tâm nằm ở điều mình đã làm và trách nhiệm cần   nhận, không nhất thiết là toàn bộ con người mình có vấn đề.', 'I recognize that   something I did or failed to do violated a value or commitment, or caused   unwanted harm. The focus is on my action and the responsibility it creates,   rather than judging my entire self as bad.', true, 70),
('EMO_071', 'EFAM_009', 'Hối hận', 'Remorseful', '↩️', '#9D4EDD', 'Mình cảm nhận sâu tác   động của việc mình đã làm và thật sự ước rằng nó đã không xảy ra theo cách   ấy. Cảm xúc này thường đi cùng mong muốn nhận trách nhiệm, xin lỗi, bù đắp   hoặc làm khác đi nếu còn cơ hội.', 'I feel the impact of   what I have done and deeply wish it had happened differently. Remorse usually   includes a genuine desire to take responsibility, apologize, repair, or act   differently if possible.', true, 71),
('EMO_072', 'EFAM_009', 'Nhục nhã', 'Humiliated', '😳', '#8F5BD7', 'Mình cảm thấy phẩm   giá đã bị hạ thấp trước người khác, thường vì bị chế giễu, phơi bày, làm mất   mặt hoặc đặt vào vị thế kém giá trị. Khác với xấu hổ có thể phát sinh từ cách   mình nhìn chính mình, nhục nhã gắn rõ hơn với cách người khác đã đối xử với   mình.', 'I feel that my   dignity has been lowered before others through ridicule, exposure,   degradation, or loss of face. Unlike shame that may arise from my own   self-judgment, humiliation is more clearly linked to how others have treated   me.', true, 72),
('EMO_073', 'EFAM_009', 'Tự trách', 'Self-blaming', '🪞', '#B185DB', 'Mình đang quay sự   phán xét vào bản thân và liên tục nhắc lại điều mình đã làm, chưa làm hoặc lẽ   ra phải làm khác. Cảm giác này dễ khiến trách nhiệm thực tế biến thành một   kết luận rộng hơn rằng mọi chuyện đều là lỗi của mình.', 'I am turning judgment   inward and repeatedly revisiting what I did, failed to do, or should have   done differently. Self-blame can expand a realistic responsibility into a   broader conclusion that everything is my fault.', true, 73),
('EMO_074', 'EFAM_010', 'Chán', 'Bored', '🥱', '#6C757D', 'Điều đang diễn ra   không đủ mới, đủ thử thách hoặc đủ liên quan để giữ sự chú ý và sinh khí của   mình. Mình muốn rời khỏi nó, tìm một kích thích khác hoặc cảm thấy thời gian   đang trôi rất chậm.', 'What is happening   feels insufficiently novel, challenging, or relevant to hold my attention and   vitality. I want to disengage, seek something else, or feel that time is   moving very slowly.', true, 74),
('EMO_075', 'EFAM_010', 'Nản lòng', 'Discouraged', '💧', '#64748B', 'Sau thất bại, vật cản   hoặc một thời gian cố gắng mà chưa thấy kết quả, lòng tin và năng lượng để   tiếp tục đang giảm xuống. Mình chưa hẳn tin rằng không còn hy vọng, nhưng bắt   đầu không chắc cố thêm có còn đáng hay có tạo ra khác biệt không.', 'After setbacks or   prolonged effort without progress, my confidence and energy to continue are   declining. I may not believe that all hope is gone, but I am beginning to   question whether further effort is worthwhile or effective.', true, 75),
('EMO_076', 'EFAM_010', 'Vô vọng', 'Hopeless', '🌘', '#475569', 'Mình khó nhìn thấy   một tương lai có thể tốt hơn hoặc một con đường thực sự dẫn ra khỏi tình hình   hiện tại. Không chỉ thiếu sức để tiếp tục, mình còn khó tin rằng việc tiếp   tục có thể tạo ra một khác biệt có ý nghĩa.', 'I struggle to imagine   a better future or a viable way out of the current situation. I am not only   low on energy; I also find it difficult to believe that continued effort   could make a meaningful difference.', true, 76),
('EMO_077', 'EFAM_010', 'Lạc lõng', 'Alienated', '🚪', '#778DA9', 'Mình có mặt nhưng cảm   thấy không cùng nhịp, không tìm được vị trí hoặc như đang đứng bên ngoài nơi   mình hiện diện. Có thể xung quanh vẫn có người, nhưng mình không cảm thấy   mình thuộc về hoặc được hiểu trong bối cảnh ấy.', 'I am present but feel   out of sync, without a place, or outside the situation I am in. People may be   around me, yet I do not feel that I belong or am understood within the   context.', true, 77),
('EMO_078', 'EFAM_010', 'Trống rỗng', 'Empty', '🫙', '#4361EE', 'Bên trong mình có cảm   giác thiếu một điều đáng lẽ phải hiện diện — cảm xúc, kết nối, ý nghĩa hoặc   sinh khí — nhưng mình chưa chắc điều gì đang thiếu. Mình không hoàn toàn   không cảm nhận được; mình cảm nhận khá rõ chính khoảng trống ấy.', 'I sense the absence   of something that should be present—emotion, connection, meaning, or   vitality—without necessarily knowing what is missing. I am not feeling   nothing; I can feel the emptiness itself.', true, 78),
('EMO_079', 'EFAM_010', 'Tê lì', 'Numb', '🧊', '#495057', 'Cảm xúc như bị giảm   âm lượng hoặc ở quá xa để mình chạm tới. Đây có thể là cách mình tạm đóng bớt   tín hiệu sau khi đã phải chịu quá nhiều, chứ không nhất thiết có nghĩa là   mình không quan tâm.', 'My emotions feel   muted or too distant to reach. Numbness may be a protective reduction of   emotional signals after too much strain rather than evidence that I do not   care.', true, 79),
('EMO_080', 'EFAM_010', 'Kiệt sức', 'Exhausted', '🪫', '#667085', 'Nguồn lực thể chất   lẫn tinh thần của mình đã xuống rất thấp sau một thời gian tiêu hao hoặc phải   cố kéo dài. Mình không chỉ mệt; mình cảm thấy khó tiếp tục đáp ứng, quan tâm   hoặc tự phục hồi nếu vẫn phải giữ nhịp như hiện tại.', 'My physical and   emotional resources have fallen very low after prolonged effort or strain. I   am not simply tired; continuing to perform, care, or recover feels difficult   if the current pace remains unchanged.', true, 80),
('EMO_081', 'EFAM_010', 'Mất động lực', 'Demotivated', '🧯', '#5C677D', 'Điều từng khiến mình   muốn bắt đầu hoặc tiếp tục không còn tạo được lực kéo như trước. Mình có thể   vẫn biết việc ấy quan trọng, nhưng không còn cảm thấy lý do, phần thưởng hoặc   năng lượng đủ gần để hành động.', 'What once moved me to   begin or continue no longer creates the same pull. I may still know that the   task matters, but the reason, reward, or energy no longer feels close enough   to support action.', true, 81),
('EMO_082', 'EFAM_010', 'Mất phương hướng', 'Directionless', '🧭', '#6B7280', 'Mình chưa nhìn thấy   điều gì đáng để hướng tới hoặc bước tiếp theo nào có ý nghĩa. Không chỉ thiếu   thông tin, mình còn cảm thấy các lựa chọn hiện tại chưa kết nối được với một   phương hướng thật sự thuộc về mình.', 'I cannot see what is   worth moving toward or which next step would feel meaningful. The problem is   not only a lack of information; the available options do not yet connect with   a direction that feels genuinely mine.', true, 82),
('EMO_083', 'EFAM_010', 'Meh – Hờ hững', 'Meh / Indifferent', '🫤', '#718096', 'Điều đang xảy ra   không tạo nhiều hứng thú, khó chịu hay ý nghĩa; phản ứng bên trong chỉ ở mức   “ừ, cũng được”. Mình vẫn nhận biết được trải nghiệm, nhưng không cảm thấy bị   kéo lại gần hay đẩy ra xa một cách rõ rệt.', 'What is happening   creates little interest, discomfort, or significance; my inner response is   simply “meh.” I remain aware of the experience, but I am not clearly drawn   toward it or pushed away from it.', true, 83),
('EMO_084', 'EFAM_004', 'Can đảm', 'Courageous', '🦁', '#00B894', 'Mình vẫn nhận ra nỗi   sợ, rủi ro hoặc sự khó khăn, nhưng sẵn sàng bước về phía điều quan trọng thay   vì để nỗi sợ quyết định hoàn toàn. Can đảm không phải là không sợ; nó là khả   năng hành động dù sợ vẫn đang có mặt.', 'I recognize fear,   risk, or difficulty, yet remain willing to move toward what matters. Courage   is not the absence of fear, but the capacity to act while fear is still   present.', true, 84),
('EMO_085', 'EFAM_004', 'Tự tin', 'Confident', '🌟', '#2A9D8F', 'Mình tin rằng mình có   đủ khả năng để đối diện, học, thích nghi hoặc tìm cách xử lý điều đang ở   trước mặt. Tự tin không cần chắc chắn mình sẽ thành công; chỉ cần tin rằng   mình có thể tham gia và ứng phó.', 'I trust my ability to   face, learn, adapt, or find a way through what is ahead. Confidence does not   require certainty of success, only the belief that I can engage and respond.', true, 85),
('EMO_086', 'EFAM_004', 'Quyết tâm', 'Determined', '🏹', '#06A77D', 'Mình đã chọn một   hướng và đang muốn tập trung năng lượng để theo nó, kể cả khi cần vượt qua   khó khăn hoặc sự chậm trễ. Khác với một đợt hứng khởi nhất thời, quyết tâm có   yếu tố cam kết với điều mình đã chọn.', 'I have chosen a   direction and want to concentrate my energy on pursuing it despite difficulty   or delay. Unlike a temporary burst of enthusiasm, determination includes   commitment to the course I have chosen.', true, 86),
('EMO_087', 'EFAM_004', 'Chân thật – Được là   mình', 'Authentic / Being   myself', '🪞', '#02C39A', 'Điều mình nói, chọn   và thể hiện đang tương đối gần với cảm xúc, giá trị và con người thật bên   trong. Mình không phải chỉnh sửa, thu nhỏ hoặc phản bội mình quá nhiều chỉ để   vừa với kỳ vọng của người khác.', 'What I express and   choose is reasonably aligned with my feelings, values, and inner self. I do   not have to excessively edit, shrink, or betray myself in order to fit other   people''s expectations.', true, 87),
('EMO_088', 'EFAM_011', 'Bất ngờ', 'Surprised', '😲', '#E56BDE', 'Một điều vừa xảy ra   khác với điều mình dự đoán, khiến sự chú ý lập tức dừng lại và hướng về nó.   Bất ngờ tự nó chưa hẳn vui hay khó chịu; sắc thái sẽ hình thành sau khi mình   hiểu điều vừa xảy ra có ý nghĩa gì.', 'Something differs   from what I expected, immediately interrupting and redirecting my attention.   Surprise is not inherently pleasant or unpleasant; its emotional tone   develops after I interpret what happened.', true, 88),
('EMO_089', 'EFAM_011', 'Kinh ngạc', 'Amazed', '🤯', '#D65DB1', 'Mình bất ngờ trước   điều đặc biệt, ấn tượng hoặc vượt xa kỳ vọng theo một hướng khiến mình bị thu   hút. Không chỉ dừng lại để tiếp nhận, mình còn muốn nhìn thêm, hiểu thêm hoặc   ngưỡng mộ điều vừa xuất hiện.', 'I am surprised by   something remarkable or far beyond expectation in a way that draws me in. I   do not merely pause to process it; I want to keep looking, understand more,   or admire what has appeared.', true, 89),
('EMO_090', 'EFAM_011', 'Sửng sốt', 'Shocked', '⚡', '#C77DFF', 'Một thông tin hoặc sự   kiện quá đột ngột, nghiêm trọng hoặc khác xa hình dung khiến mình tạm thời   khó tiếp nhận và phản ứng. Mình có thể đứng hình, không biết nói gì hoặc cần   thêm thời gian để tin rằng điều ấy là thật.', 'An event or piece of   information is so sudden, serious, or far from expectation that I temporarily   struggle to process it. I may freeze, lose my words, or need time to accept   that it is real.', true, 90),
('EMO_091', 'EFAM_011', 'Lạ lẫm', 'Unfamiliar', '🛸', '#8A5CF6', 'Mình đang đứng trước   một người, nơi chốn hoặc trải nghiệm chưa có bản đồ quen thuộc trong đầu. Sự   mới lạ khiến mình vừa quan sát nhiều hơn, vừa chưa biết nên tiến gần, giữ   khoảng cách hay phản ứng thế nào.', 'I am encountering a   person, place, or experience for which I have no familiar map. The novelty   makes me observe more closely while remaining unsure whether to approach,   keep distance, or respond in another way.', true, 91),
('EMO_092', 'EFAM_007', 'Ghê tởm', 'Disgusted', '🤢', '#F97316', 'Mình cảm nhận một thứ   là bẩn, ô nhiễm, sai trái hoặc không thể tiếp nhận và muốn tránh xa hay loại   bỏ nó. Phản ứng này có thể được khơi lên bởi mùi vị, hình ảnh, hành vi hoặc   một vi phạm đạo đức sâu.', 'I perceive something   as contaminated, offensive, morally repellent, or impossible to take in,   creating an urge to reject or move away from it. The response may be   triggered by sensory input, behavior, or a profound moral violation.', true, 92),
('EMO_093', 'EFAM_007', 'Khinh miệt', 'Contemptuous', '👎', '#E85D04', 'Mình mất sự tôn trọng   và nhìn một người hoặc hành vi như thấp kém, không xứng đáng hoặc không đáng   được xem ngang hàng. Cảm xúc này thường lạnh hơn tức giận và tạo ra khoảng   cách rõ hơn giữa mình với đối tượng.', 'I lose respect and   view a person or behavior as inferior, unworthy, or beneath equal regard.   Contempt is often colder than anger and creates a stronger interpersonal   distance.', true, 93),
('EMO_094', 'EFAM_009', 'Đố kỵ', 'Envious', '🟢', '#84CC16', 'Mình đau hoặc khó   chịu khi thấy người khác có một phẩm chất, cơ hội, vị trí hay điều mình cũng   khao khát nhưng hiện chưa có. Cảm xúc này có thể chỉ ra điều mình thật sự   mong muốn, dù nó cũng dễ kéo mình vào so sánh và hạ thấp bản thân.', 'I feel pain or   discomfort because another person has a quality, opportunity, position, or   possession that I also desire. Envy can reveal what I genuinely long for,   while also pulling me into comparison and self-diminishment.', true, 94),
('EMO_095', 'EFAM_009', 'Ghen', 'Jealous', '💚', '#65A30D', 'Mình sợ mất sự quan   tâm, vị trí hoặc mối quan hệ đang quan trọng với mình vào tay một người khác.   Trọng tâm không phải là người kia có điều mình muốn, mà là điều mình đang có   có thể bị lấy đi, chia sẻ hoặc thay thế.', 'I fear losing valued   attention, position, or a relationship to someone else. The core concern is   not that the other person has what I want, but that something I already value   may be taken, shared, or replaced.', true, 95),
('EMO_096', 'EFAM_009', 'Tự hào', 'Proud', '🏅', '#E9C46A', 'Mình đang ghi nhận   một nỗ lực, phẩm chất, lựa chọn hoặc thành quả có ý nghĩa của bản thân. Cảm   giác này không chỉ nói rằng mình đã đạt được điều gì, mà còn rằng điều ấy   phản ánh phần con người hoặc giá trị mà mình muốn trân trọng.', 'I am recognizing a   meaningful effort, quality, choice, or achievement in myself. Pride is not   only about having accomplished something; it also reflects a part of who I am   or what I value that feels worthy of appreciation.', true, 96),
('EMO_097', 'EFAM_011', 'Choáng ngợp trước   điều lớn lao', 'Awe', '🌌', '#B565D9', 'Mình đang đứng trước   một điều rộng lớn, đẹp đẽ, mạnh mẽ hoặc vượt ngoài khung hiểu biết quen   thuộc, khiến mình vừa mở ra vừa cảm thấy mình nhỏ lại. Trải nghiệm này có thể   làm cách mình nhìn thế giới rộng hơn, thay vì chỉ khiến mình không xử lý nổi.', 'I am encountering   something vast, beautiful, powerful, or beyond my usual frame of   understanding, making me feel both expanded and smaller. Awe can enlarge my   perspective rather than simply exceed my capacity to cope.', true, 97),
('EMO_098', 'EFAM_002', 'Trung tính hiện diện', 'Neutral presence', '😐', '#A0AEC0', 'Mình không vui rõ,   cũng không buồn hay khó chịu rõ; mình đơn giản đang hiện diện và tiếp nhận   khoảnh khắc như nó là. Cảm xúc không mạnh nhưng sự nhận biết vẫn còn, nên   trạng thái này khác với tê lì hay mất kết nối.', 'I am not clearly   joyful, sad, or distressed; I am simply present and receiving the moment as   it is. Emotion is low in intensity, but awareness remains intact, which   distinguishes this state from numbness or disconnection.', true, 98),
('EMO_099', 'EFAM_001', 'Jovial', 'Jovial', '😄', '#F7C948', 'Mình đang vui theo   một cách cởi mở, thân thiện và dễ lan sang những người xung quanh. Không chỉ   bản thân thấy vui, mình còn muốn trò chuyện, pha trò, hòa vào không khí chung   và giúp khoảnh khắc giữa mọi người trở nên nhẹ nhàng hơn.', 'I feel cheerful in an   open, sociable, and good-humored way that can easily spread to those around   me. My enjoyment is not entirely private; I feel inclined to talk, joke, join   the shared atmosphere, and make the moment more pleasant for others.', true, 99),
('EMO_100', 'EFAM_002', 'Sảng khoái', 'Refreshed', '🌊', '#63C7B2', 'Mình cảm thấy như vừa   được làm mới sau khi một phần mệt mỏi, bí bách hoặc nặng nề đã được rũ bớt.   Đầu óc tỉnh hơn, tinh thần sáng hơn và cơ thể có thêm sinh khí để trở lại với   điều đang diễn ra.', 'I feel renewed after   some tiredness, heaviness, or stagnation has cleared away. My mind feels   fresher, my mood brighter, and my body more alive and ready to re-engage with   what is happening.', true, 100),
('EMO_101', 'EFAM_004', 'Phóng khoáng', 'Free-spirited', '🕊️', '#2EC4B6', 'Mình cảm thấy tự do   hơn khỏi những quy tắc vụn vặt, sự dè giữ hoặc nhu cầu phải kiểm soát mọi thứ   thật chặt. Mình có thêm không gian để sống rộng rãi, cởi mở và để bản thân   cũng như người khác được là chính mình.', 'I feel less   constrained by minor conventions, excessive caution, or the need to control   everything tightly. There is more room to be open, generous, and   free-spirited, allowing both myself and others to exist more fully as we are.', true, 101),
('EMO_102', 'EFAM_008', 'Buồn & nhớ khắc   khoải', 'Saudade', '🌙', '#4F6FAE', 'Mình đang nhớ một   người, nơi chốn, thời điểm hoặc phần đời từng rất có ý nghĩa, với cảm giác   vừa ấm áp vừa buồn vì nó đang vắng mặt. Trong nỗi nhớ có cả mong muốn được   trở lại và sự nhận biết rằng điều ấy có thể không bao giờ trở về đúng như   xưa.', 'I feel a deep,   melancholic longing for a person, place, time, or part of life that once   mattered greatly and is now absent. The feeling holds both warmth and sorrow,   including a wish to return alongside the recognition that what is missed may   never come back in quite the same form.', true, 102),
('EMO_103', 'EFAM_004', 'Sonder', 'Sonder', '🏙️', '#8C7AE6', 'Mình chợt nhận ra   rằng mỗi người xa lạ đi ngang qua đều đang sống một cuộc đời đầy đủ, phức tạp   và sống động như chính mình. Họ cũng có những mối quan hệ, nỗi lo, ký ức và   câu chuyện mà mình có thể sẽ không bao giờ biết tới, và mình chỉ xuất hiện   rất nhỏ trong thế giới của họ.', 'I suddenly realize   that every stranger passing by is living a life as vivid, complex, and   complete as my own. They have relationships, worries, memories, and unfolding   stories I may never know, while I may appear only briefly at the edge of   their world.', true, 103),
('EMO_104', 'EFAM_010', 'Mauerbauertraurigkeit', 'Mauerbauertraurigkeit', '🧱', '#596275', 'Mình bỗng muốn đẩy   người khác ra xa, kể cả những người mình thật sự quý và thường thấy dễ chịu   khi ở bên. Mình có thể trở nên lạnh, né tránh hoặc tự dựng một bức tường, dù   một phần trong mình vẫn biết rằng sự xa cách này không phản ánh điều mình   thật sự cảm thấy về họ.', 'I feel an   inexplicable urge to push people away, including people I genuinely care   about and usually enjoy being with. I may become distant, avoidant, or   emotionally walled off even while recognizing that this withdrawal does not   fully reflect how I feel about them.', true, 104),
('EMO_105', 'EFAM_006', 'Sợ sự bình thường -   mờ nhạt', 'Koinophobia', '🪞', '#D77A22', 'Mình sợ rằng cuộc đời   mình đang quá bình thường, không đủ đặc biệt hoặc sẽ trôi qua mà không để lại   điều gì có ý nghĩa. Cảm giác này có thể khiến mình liên tục phải chứng minh,   đạt thêm hoặc tìm một dấu ấn lớn hơn để cảm thấy đời mình không bị lãng phí.', 'I fear that my life   may be too ordinary, unremarkable, or lacking in lasting significance. This   anxiety can create pressure to keep proving myself, achieving more, or   pursuing a larger legacy so that my life does not feel wasted.', true, 105),
('EMO_106', 'EFAM_010', 'Altschmerz', 'Altschmerz', '🩹', '#6B7280', 'Mình mệt mỏi vì cứ   phải quay lại với những vấn đề, nỗi lo hoặc điểm mắc cũ mà mình đã mang theo   quá lâu. Không chỉ buồn vì chúng vẫn còn đó, mình còn thấy chán chính việc   phải tiếp tục nghĩ, phân tích và vật lộn với cùng một câu chuyện quen thuộc.', 'I feel weary of   revisiting the same old problems, anxieties, or personal struggles that have   followed me for far too long. I am not only distressed that they remain   unresolved; I am tired of having to think about, analyze, and struggle with   the same familiar story again.', true, 106),
('EMO_107', 'EFAM_003', 'Mamihlapinatapai', 'Mamihlapinatapai', '👁️', '#A078C9', 'Giữa mình và một   người khác đang có một sự hiểu ngầm rằng cả hai đều muốn một điều giống nhau,   nhưng không ai muốn là người mở lời hoặc bắt đầu trước. Khoảnh khắc ấy chứa   sự kết nối, mong chờ và do dự cùng lúc, như thể mỗi người đang lặng lẽ trao   quyền khởi đầu cho người còn lại.', 'Another person and I   seem to share an unspoken understanding that we both want the same thing, yet   neither of us is willing to initiate it. The moment holds connection,   anticipation, and hesitation at once, as though each of us is silently   offering the first move to the other.', true, 107),
('EMO_108', 'EFAM_008', 'Đời... vô thường ha?', 'Mono no Aware', '🍃', '#8D86C9', 'Mình chợt cảm nhận vẻ   đẹp của một điều chính vì biết rằng nó đang đổi thay và không thể tồn tại   mãi. Trong cảm giác ấy có sự nâng niu, một nỗi buồn nhẹ và sự chấp nhận rằng   tính mong manh, thoáng qua cũng là một phần khiến khoảnh khắc trở nên quý   giá.', 'I feel the beauty of   something more deeply because I know that it is changing and cannot last   forever. The experience holds tenderness, gentle sadness, and an acceptance   that impermanence is part of what makes the moment precious.', true, 108),
('EMO_109', 'EFAM_005', 'Bất lực không thể gọi   tên cảm xúc', 'Alexithymia', '🫧', '#8795A1', 'Mình biết bên trong   đang có điều gì đó, nhưng khó nhận ra chính xác đó là cảm xúc gì hoặc diễn   đạt nó thành lời. Các tín hiệu có thể hiện ra qua cơ thể, suy nghĩ hoặc hành   vi trước khi mình hiểu được trải nghiệm cảm xúc đang diễn ra.', 'I know that something   is happening inside me, but I find it difficult to identify the specific   feeling or put it into words. The experience may first appear through bodily   sensations, thoughts, or behavior before I can understand its emotional   meaning.', true, 109),
('EMO_110', 'EFAM_004', 'Metanoia', 'Metanoia', '🦋', '#5FAF9F', 'Một sự thay đổi sâu   đang diễn ra trong cách mình nhìn bản thân, người khác hoặc cuộc sống. Không   chỉ là đổi ý nhất thời, mình cảm thấy một hướng cũ không còn phù hợp và một   cách sống, niềm tin hoặc con người mới đang dần hình thành.', 'I am undergoing a   profound change in how I understand myself, other people, or life. This is   more than a temporary change of mind; an old direction no longer fits, and a   new way of living, believing, or being is beginning to emerge.', true, 110),
('EMO_111', 'EFAM_008', 'Hoài niệm ngọt ngàooo', 'Natsukashii', '🎞️', '#6F86C5', 'Một ký ức, nơi chốn,   âm thanh hoặc điều quen thuộc từ quá khứ vừa trở lại và làm lòng mình ấm lên.   Mình nhớ điều ấy với sự trìu mến và vui vì từng có nó, dù cũng có một chút se   lòng vì khoảng thời gian ấy đã đi qua.', 'A memory, place,   sound, or familiar part of the past returns and warms me from within. I   remember it with fondness and gratitude that it existed, while also feeling a   gentle ache because that time has passed.', true, 111),
('EMO_112', 'EFAM_009', 'Nụ cười… mất dần nhân   tính', 'Schadenfreude', '😏', '#C98B38', 'Mình cảm thấy một   chút vui, hả hê hoặc thỏa mãn khi người khác gặp thất bại, mất lợi thế hoặc   chịu một hệ quả không mong muốn. Cảm giác này có thể mạnh hơn khi mình cho   rằng họ đã kiêu ngạo, đối xử không công bằng hoặc đáng phải nhận hậu quả ấy.', 'I feel pleasure,   satisfaction, or a sense of vindication when another person experiences   failure, disadvantage, or misfortune. The feeling may become stronger when I   believe that the person acted arrogantly, unfairly, or deserved the   consequence.', true, 112),
('EMO_113', 'EFAM_011', 'Dépaysement', 'Dépaysement', '🧳', '#7E88AE', 'Mình cảm thấy lạc   nhịp và hơi mất phương hướng khi bị đặt vào một nơi, môi trường hoặc nếp sống   rất khác với điều quen thuộc. Việc rời khỏi những dấu hiệu từng giúp mình   biết mình là ai và đang ở đâu có thể vừa mở ra điều mới, vừa tạo cảm giác xa   lạ hoặc như không còn đứng trên nền của mình.', 'I feel disoriented   and out of place in an environment, culture, or way of life that differs   greatly from what is familiar. Being separated from the cues that normally   help me know who I am and where I belong can feel both stimulating and   estranging.', true, 113),
('EMO_114', 'EFAM_005', 'Chộn rộn', 'Fluttery anticipation', '🦋', '#9B7AE8', 'Trong lòng mình đang   xôn xao và khó yên vì có một điều sắp đến, một mong muốn vừa được đánh thức   hoặc một thay đổi đang tới gần. Cảm giác có thể pha cả háo hức, hồi hộp và   bồn chồn, nhưng chưa nghiêng hẳn về vui hay lo.', 'I feel inwardly   stirred and unable to settle because something is approaching, a desire has   been awakened, or change is drawing near. The feeling may blend anticipation,   nervousness, and restlessness without becoming clearly joyful or anxious.', true, 114),
('EMO_115', 'EFAM_001', 'Cưng xỉu!!!! Moeeee', 'Gigil', '🥹', '#FFB347', 'Mình thấy ai đó hoặc   điều gì đó đáng yêu đến mức cảm xúc dâng lên quá mạnh, khiến mình muốn ôm   chặt, véo má hoặc siết lại vì không biết phải chứa sự dễ thương ấy thế nào.   Dù biểu hiện có vẻ mạnh, ý hướng bên trong vẫn là trìu mến và vui thích,   không phải muốn làm đau.', 'I find someone or   something so overwhelmingly adorable that I feel an urge to squeeze, pinch,   clench, or hold them tightly because the cuteness feels almost too intense to   contain. Although the expression may seem forceful, the underlying feeling is   affectionate and playful rather than harmful.', true, 115),
('EMO_116', 'EFAM_003', 'Vui kiểu... vương vấn   sau ăn uống nhâm nhi.', 'Sobremesa', '☕', '#F08FA3', 'Bữa ăn đã kết thúc   nhưng mình vẫn muốn ở lại bên bàn, tiếp tục trò chuyện, cười đùa và tận hưởng   sự hiện diện của những người đang ở cùng. Niềm vui không còn nằm ở món ăn, mà   ở cảm giác thời gian được kéo dài vì chưa ai muốn kết nối này kết thúc.', 'The meal has ended,   but I still want to remain at the table, talking, laughing, and enjoying the   company of the people around me. The pleasure no longer comes mainly from the   food, but from allowing the shared connection to linger without rushing to   end it.', true, 116),
('EMO_117', 'EFAM_010', 'Kiểu... cuộn mình   trong chăn ấm', 'Clinomania', '🛌', '#7B879D', 'Mình cảm thấy một lực   kéo mạnh muốn tiếp tục nằm lại trong chăn nệm, dù chưa chắc còn buồn ngủ.   Chiếc giường tạo cảm giác ấm, kín và an toàn hơn thế giới bên ngoài, khiến   việc bước ra để bắt đầu ngày mới hoặc trở lại với trách nhiệm trở nên khó   khăn.', 'I feel a powerful   pull to remain in bed even when I may no longer be sleepy. The bed feels   warm, enclosed, and safer than the world outside, making it difficult to get   up and re-enter the day or its responsibilities.', true, 117)
insert into public.need_groups (need_group_id, group_code, group_name_vn, group_name_en, color_hex, active, sort_order)
values
('NGRP_001', 'Physical_Foundation_Safety', 'Thể chất & nền an toàn', 'Physical Foundations & Safety', '#0077B6', true, 1),
('NGRP_002', 'Clarity_Agency', 'Rõ ràng & tự chủ', 'Clarity & Agency', '#7B2CBF', true, 2),
('NGRP_003', 'Authenticity_Dignity', 'Chân thật & phẩm giá', 'Authenticity & Dignity', '#F97316', true, 3),
('NGRP_004', 'Connection_Belonging', 'Kết nối & thuộc về', 'Connection & Belonging', '#FF3D71', true, 4),
('NGRP_005', 'Growth_Meaning', 'Phát triển & ý nghĩa', 'Growth & Meaning', '#06D6A0', true, 5),
('NGRP_006', 'Aliveness_Wholeness', 'Sống động & trọn vẹn', 'Aliveness & Wholeness', '#F72585', true, 6)
insert into public.needs (need_id, need_group_id, need_name_vn, need_name_en, emoji, color_hex, description_vn, description_en, active, sort_order)
values
('NEED_001', 'NGRP_001', 'Được duy trì & phục hồi thể chất', 'Physical sustenance & recovery', '🫀', '#14B8A6', 'Mình cần cơ thể có đủ thức ăn, nước, giấc ngủ, chuyển động, sự dễ chịu và thời gian hồi lại để tiếp tục sống và hoạt động mà không phải cứ vay mượn phần sức đã cạn.', 'I need enough food, water, sleep, movement, physical comfort, and recovery time for my body to keep living and functioning without continually borrowing from depleted reserves.', true, 1),
('NEED_002', 'NGRP_001', 'Được an toàn', 'Safety', '🛡️', '#2563EB', 'Mình cần biết rằng mình không đang bị đe dọa, xâm phạm hay đặt vào tình huống vượt quá sức chống đỡ. Khi đủ an toàn, mình mới có thể bớt phòng thủ và thả lỏng.', 'I need to know that I am not being threatened, violated, or placed in a situation beyond my ability to cope. When I feel sufficiently safe, I can lower my defenses and begin to relax.', true, 2),
('NEED_003', 'NGRP_001', 'Được ổn định & nhất quán', 'Stability & consistency', '⚓', '#4F46E5', 'Mình cần có những điều đủ đáng tin để biết mình đang đứng trên nền nào. Không phải mọi thứ đều bất biến, nhưng mình không muốn liên tục dè chừng điều gì sẽ lại thay đổi, thất hứa hoặc đổ vỡ.', 'I need enough reliability and continuity to know what ground I am standing on. Not everything must remain unchanged, but I do not want to be constantly bracing for another shift, broken promise, or collapse.', true, 3),
('NEED_004', 'NGRP_002', 'Có đủ thông tin để hiểu & định hướng', 'Information, understanding & direction', '🧭', '#F59E0B', 'Mình cần có đủ dữ kiện và bối cảnh để hiểu chuyện gì đang xảy ra, điều gì liên quan đến mình và mình có thể đi tiếp từ đâu, thay vì phải tự lấp khoảng trống bằng suy đoán hoặc tưởng tượng.', 'I need enough information and context to understand what is happening, what concerns me, and where I can go from here, rather than filling every gap with guesses or imagined possibilities.', true, 4),
('NEED_005', 'NGRP_002', 'Có quyền tự chủ & lựa chọn', 'Autonomy & choice', '🎛️', '#8B5CF6', 'Mình cần được tự quyết những phần thực sự thuộc về đời mình: được nói có, nói không, đổi ý và lựa chọn cách mình tham gia mà không bị ép buộc bởi sợ hãi, tội lỗi hay áp lực.', 'I need to have a meaningful say in the parts of life that belong to me—to consent, refuse, change my mind, and choose how I participate without being coerced by fear, guilt, or pressure.', true, 5),
('NEED_006', 'NGRP_002', 'Có không gian riêng & quyền được giữ riêng', 'Privacy & personal space', '🔐', '#6366F1', 'Mình cần có một phần thời gian, không gian, suy nghĩ và đời sống chỉ thuộc về mình; được lựa chọn điều gì sẽ chia sẻ, với ai, vào lúc nào và đến mức nào.', 'I need some time, space, thoughts, and areas of life that remain my own, along with the right to choose what I share, with whom, when, and to what extent.', true, 6),
('NEED_007', 'NGRP_003', 'Được chân thật & là chính mình', 'Authenticity & being myself', '🌱', '#22C55E', 'Mình cần được sống gần với điều mình thật sự cảm thấy, tin tưởng và coi trọng, thay vì thường xuyên phải diễn, thu nhỏ hoặc bẻ mình thành một phiên bản dễ được chấp nhận hơn.', 'I need to live in reasonable alignment with what I genuinely feel, believe, and value, rather than repeatedly performing, shrinking, or reshaping myself into a version that is easier for others to accept.', true, 7),
('NEED_008', 'NGRP_003', 'Phẩm giá & sự toàn vẹn được tôn trọng', 'Dignity & personal integrity', '🤝', '#F97316', 'Mình cần cơ thể, thời gian, tiếng nói, giới hạn và quyền lợi của mình được coi trọng. Mình không muốn bị hạ thấp, ép buộc, làm nhục hay đối xử như thể mình chỉ là một công cụ.', 'I need my body, time, voice, boundaries, and rights to be respected. I do not want to be degraded, coerced, humiliated, or treated as though I were merely a tool for someone else''s purposes.', true, 8),
('NEED_009', 'NGRP_004', 'Được lắng nghe & thấu hiểu', 'Being heard & understood', '👂', '#06B6D4', 'Mình cần có người thật sự nghe điều mình đang cố nói và hiểu phần trải nghiệm phía sau nó. Không nhất thiết phải đồng ý hay giải quyết giúp mình, nhưng đừng vội cắt ngang, sửa chữa hoặc diễn giải sai.', 'I need someone to genuinely hear what I am trying to say and understand the experience beneath it. They do not have to agree or solve it for me, but I need not to be interrupted, corrected too quickly, or fundamentally misread.', true, 9),
('NEED_010', 'NGRP_004', 'Được kết nối & gần gũi', 'Connection & closeness', '🔗', '#EC4899', 'Mình cần cảm thấy giữa mình và người khác có sự gặp gỡ thật sự: có hiện diện, chia sẻ, đáp lại và chạm tới nhau, chứ không chỉ cùng ở đó hoặc duy trì liên lạc bề mặt.', 'I need genuine contact with other people—presence, sharing, mutual response, and a sense of reaching one another rather than merely occupying the same space or maintaining surface-level contact.', true, 10),
('NEED_011', 'NGRP_004', 'Được quan tâm, nâng đỡ & đồng hành', 'Care, support & companionship', '🫶', '#FB7185', 'Mình cần biết rằng điều mình đang trải qua có người thật sự để tâm. Khi chặng đường dài hoặc sức mình không đủ, mình muốn có người cùng đi, cùng giữ hoặc chia bớt một phần.', 'I need to know that someone genuinely cares about what I am going through. When the road is long or my strength is not enough, I need support, shared presence, or someone willing to carry part of the weight with me.', true, 11),
('NEED_012', 'NGRP_004', 'Được thuộc về & bao hàm', 'Belonging & inclusion', '🏡', '#A855F7', 'Mình cần cảm thấy mình có một chỗ hợp lệ trong mối quan hệ, nhóm hoặc cộng đồng; được tính đến, được tham gia và không phải xóa bỏ những phần khác biệt để được ở lại.', 'I need to feel that I have a legitimate place in a relationship, group, or community—to be considered, included, and able to remain without erasing the parts of me that are different.', true, 12),
('NEED_013', 'NGRP_004', 'Được nhìn thấy & coi trọng', 'Being seen & valued', '💛', '#EAB308', 'Mình cần cảm thấy sự hiện diện, nỗ lực và điều mình mang lại không bị xem là vô hình hay hiển nhiên. Mình muốn được nhận ra như một người có trọng lượng, không chỉ khi mình hữu ích, thành công hoặc mắc lỗi.', 'I need my presence, effort, and contributions not to be invisible or taken for granted. I want to be recognized as someone who matters, not only when I am useful, successful, or making a mistake.', true, 13),
('NEED_014', 'NGRP_003', 'Được đối xử công bằng', 'Fair treatment', '⚖️', '#EF4444', 'Mình cần các quy tắc, cơ hội, trách nhiệm, nguồn lực và hệ quả được áp dụng có lý lẽ, nhất quán và tương xứng, thay vì tiêu chuẩn kép hoặc để một người phải gánh phần không thuộc về mình.', 'I need rules, opportunities, responsibilities, resources, and consequences to be applied with reason, consistency, and proportionality, rather than through double standards or by placing an unfair burden on one person.', true, 14),
('NEED_015', 'NGRP_005', 'Cảm thấy mình có năng lực & đang phát triển', 'Competence & growth', '🧩', '#10B981', 'Mình cần cảm thấy mình có thể hiểu, học, hành động, sửa sai và dần làm tốt hơn. Không cần phải giỏi ngay, nhưng mình cần thấy rằng mình không hoàn toàn bất lực và những cố gắng của mình đang đưa mình tiến lên.', 'I need to feel capable of understanding, learning, acting, correcting mistakes, and gradually improving. I do not need to be excellent immediately, but I need evidence that I am not powerless and that my efforts are helping me grow.', true, 15),
('NEED_016', 'NGRP_005', 'Có ý nghĩa & mục đích', 'Meaning & purpose', '✨', '#7C3AED', 'Mình cần cảm thấy điều mình đang sống và làm có liên hệ với một giá trị, một hướng đi hoặc điều thật sự đáng quan tâm, thay vì chỉ là chuỗi nghĩa vụ rời rạc.', 'I need to feel that what I am living and doing connects with a value, a direction, or something genuinely worth caring about, rather than being only a sequence of disconnected obligations.', true, 16),
('NEED_017', 'NGRP_006', 'Được vui chơi & cảm thấy sống động', 'Play & aliveness', '🎈', '#FF7A00', 'Mình cần có chỗ cho niềm vui, tò mò, khám phá, sáng tạo và những trải nghiệm không chỉ nhằm đạt kết quả. Mình không muốn đời sống chỉ còn là vận hành và trách nhiệm.', 'I need room for joy, curiosity, exploration, creativity, and experiences that are not solely aimed at producing results. I do not want life to become nothing more than functioning and responsibility.', true, 17),
('NEED_018', 'NGRP_006', 'Được tiếp xúc với vẻ đẹp & sự hài hòa', 'Beauty & harmony', '🌸', '#D946EF', 'Mình cần được ở gần những điều đẹp, cân đối, dễ chịu hoặc có sức gợi để giác quan và tinh thần được mở ra, dịu lại và cảm thấy đời sống không chỉ còn khô cứng, hỗn độn hay nghĩa vụ.', 'I need contact with beauty, balance, sensory ease, and evocative experiences that open and soothe my mind and senses, reminding me that life is more than harshness, disorder, and obligation.', true, 18),
('NEED_019', 'NGRP_006', 'Được hoàn tất & trọn vẹn với mình', 'Closure & inner completion', '🧵', '#0D9488', 'Mình cần có thể khép lại điều còn dang dở theo cách khiến lòng mình bớt bị kéo lại. Có khi là làm xong, hiểu ra, tiếc nuối, sửa chữa hoặc chấp nhận, để mình có thể bước tiếp mà không phủ nhận điều đã xảy ra.', 'I need to bring unfinished experiences to enough of a close that they no longer keep pulling me backward. This may mean completing, understanding, grieving, repairing, or accepting something so that I can move forward without denying what happened.', true, 19)
insert into public.contexts (context_id, context_group, context_name_vn, emoji, color_hex, description_vn, active, sort_order)
values
('CTX_001', 'work_growth', 'Công việc', '💼', '#FF9F43', 'Những trải nghiệm liên quan đến công việc, vai trò nghề nghiệp, nhiệm vụ đang đảm nhận, môi trường làm việc hoặc những người mình tương tác trong quá trình làm việc. Chọn khi câu chuyện thuộc bối cảnh công việc nói chung và không cần xác định một tình huống cụ thể hơn.', true, 1),
('CTX_002', 'work_growth', 'Học tập & phát triển', '📚', '#FF9F43', 'Những điều liên quan đến việc học, thi cử, đào tạo, tự học, rèn luyện kỹ năng hoặc quá trình nâng cao năng lực. Chọn khi trọng tâm của trải nghiệm là học hỏi, tiến bộ hoặc trở nên thành thạo hơn.', true, 2),
('CTX_003', 'work_growth', 'Deadline & khối lượng việc', '⏰', '#FF9F43', 'Những lúc công việc, bài tập hoặc trách nhiệm đang dồn lại; thời hạn đến gần; tiến độ không như mong đợi; hoặc lượng việc đang vượt quá khả năng xử lý hiện tại.', true, 3),
('CTX_004', 'work_growth', 'Feedback & đánh giá', '📝', '#FF9F43', 'Những trải nghiệm liên quan đến việc nhận, đưa hoặc chờ phản hồi về kết quả, năng lực, cách làm hoặc mức độ đáp ứng kỳ vọng. Bao gồm góp ý, review, chấm điểm, KPI, công nhận và phê bình.', true, 4),
('CTX_005', 'relationships', 'Tình cảm', '💗', '#FF8FAB', 'Những trải nghiệm liên quan đến người mình có tình cảm, mối quan hệ yêu đương, hẹn hò hoặc một kết nối mang ý nghĩa thân mật đặc biệt.', true, 5),
('CTX_006', 'relationships', 'Bạn bè', '🧑‍🤝‍🧑', '#FF8FAB', 'Những điều diễn ra giữa mình và một hoặc nhiều người bạn. Bao gồm sự đồng hành, gần gũi, chia sẻ, thay đổi trong tình bạn hoặc cảm giác về vị trí của mình trong một nhóm bạn.', true, 6),
('CTX_007', 'relationships', 'Quan hệ xã hội', '🌐', '#FF8FAB', 'Những tương tác với người quen, cộng đồng, tập thể hoặc những người không thuộc vòng quan hệ gần gũi. Chọn khi câu chuyện liên quan đến việc kết nối, hòa nhập hoặc hiện diện trong một môi trường xã hội.', true, 7),
('CTX_008', 'relationships', 'Gia đình & người thân', '🏠', '#F28482', 'Những điều liên quan đến bố mẹ, anh chị em, họ hàng, người chăm sóc hoặc những người được mình xem như gia đình. Bao gồm trách nhiệm, sự quan tâm, kỳ vọng và những trải nghiệm chung giữa những người thân.', true, 8),
('CTX_009', 'self', 'Bản thân & đời sống nội tâm', '🪞', '#C77DFF', 'Những suy nghĩ, cảm nhận và câu hỏi chủ yếu diễn ra bên trong mình, không nhất thiết bắt nguồn từ một người hay sự kiện cụ thể. Bao gồm giá trị cá nhân, niềm tin, căn tính và cách mình đang hiểu về chính mình.', true, 9),
('CTX_010', 'self', 'Tự nhìn nhận & phát triển bản thân', '🌱', '#C77DFF', 'Những lúc mình đang đánh giá bản thân, nhận ra một khuôn mẫu, suy nghĩ về điều cần thay đổi hoặc hình dung phiên bản mình muốn trở thành. Bao gồm tự so sánh, đặt tiêu chuẩn và quá trình trưởng thành cá nhân.', true, 10),
('CTX_011', 'self', 'Sức khỏe & thể chất', '💪', '#00C2A8', 'Những trải nghiệm liên quan đến cơ thể, sức khỏe và việc chăm sóc thể chất. Bao gồm vận động, tập luyện, chơi thể thao, khám sức khỏe, ăn uống, giấc ngủ, mức năng lượng, nghỉ ngơi, phục hồi hoặc những thay đổi và cảm nhận về cơ thể. Chọn khi cơ thể hoặc sức khỏe là một phần quan trọng của điều mình đang ghi nhận.', true, 11),
('CTX_012', 'life_resources', 'Tiền bạc & tài chính', '💰', '#F6C945', 'Những điều liên quan đến thu nhập, chi tiêu, mua sắm, tiết kiệm, nợ, kế hoạch tài chính hoặc cảm giác an toàn về tiền bạc và nguồn lực vật chất.', true, 12),
('CTX_013', 'life_resources', 'Mạng xã hội & không gian số', '📱', '#4D96FF', 'Những trải nghiệm diễn ra trên mạng xã hội, tin nhắn, nền tảng số, tin tức hoặc môi trường online. Bao gồm việc đăng tải, chờ phản hồi, tiếp nhận quá nhiều thông tin hoặc quan sát cuộc sống của người khác qua màn hình.', true, 13),
('CTX_014', 'change_direction', 'Thay đổi & chuyển tiếp', '🔄', '#9B8AFB', 'Những giai đoạn một điều quen thuộc đang bắt đầu, kết thúc hoặc chuyển sang một hình thức mới. Bao gồm đổi công việc, chuyển nơi ở, thay đổi vai trò, kết thúc một giai đoạn hoặc bước vào một chương mới.', true, 14),
('CTX_015', 'change_direction', 'Quyết định & lựa chọn', '🛤️', '#9B8AFB', 'Những tình huống mình cần cân nhắc giữa nhiều hướng đi hoặc chưa biết nên tiếp tục, dừng lại, chấp nhận, từ chối hay để điều gì đó sang một thời điểm khác.', true, 15),
('CTX_016', 'other', 'Khác', '✨', '#718096', 'Chọn khi điều mình đang ghi nhận không thật sự phù hợp với bất kỳ Context nào phía trên, hoặc khi mình chưa muốn xác định rõ bối cảnh. Có thể viết thêm trong phần ghi chú nếu cần.', true, 16)
insert into public.unknown_prompts (prompt_id, emoji, prompt_text_vn, active, sort_order)
values
('UPR_001', '🎨', 'Nếu điều vừa diễn ra có một màu sắc, nó sẽ là màu gì?', true, 1),
('UPR_002', '🔁', 'Có một câu nói, hình ảnh hoặc suy nghĩ nào cứ liên tục lặp lại trong đầu mình không?', true, 2),
('UPR_003', '🌦️', 'Nếu bên trong mình lúc này là một kiểu thời tiết, bầu trời ấy đang như thế nào?', true, 3),
('UPR_004', '✨', 'Nếu mọi thứ trở nên khác đi đúng với điều mình mong muốn, thì nó sẽ khác như thế nào?', true, 4),
('UPR_005', '🧩', 'Nếu khoảnh khắc này là một mảnh ghép, mình nghĩ nó thuộc về bức tranh nào?', true, 5),
('UPR_006', '🚪', 'Mình đã sẵn sàng để câu trả lời được phép xuất hiện chưa?', true, 6),
('UPR_007', '🙈', 'Liệu mình có đang né tránh điều gì đó không?', true, 7),
('UPR_008', '🪞', 'Trạng thái hiện tại có đang nói với mình điều gì về bản thân — về con người, giá trị, niềm tin, nhu cầu hoặc một điều nào khác không?', true, 8),
('UPR_009', '💫', 'Trong tất cả những gì vừa diễn ra, có điều gì vừa chạm đến mình không?', true, 9),
('UPR_010', '💓', 'Mình có đang rung động hoặc xúc động vì điều gì không?', true, 10),
('UPR_011', '🛡️', 'Mình có đang cố bảo vệ điều gì bằng cách im lặng, tránh né hoặc giữ khoảng cách không?', true, 11),
('UPR_012', '🩹', 'Mình có đang… tổn thương không?', true, 12),
('UPR_013', '🤲', 'Mình đang mong nhận được điều gì từ người khác, từ hoàn cảnh hoặc từ chính mình?', true, 13),
('UPR_014', '⚖️', 'Có điều gì trong tình huống này đang khiến mình cảm thấy không công bằng, không cân bằng hoặc không đúng với mình không?', true, 14),
('UPR_015', '🔄', 'Mình đã phản ứng ra sao với những điều vừa diễn ra? Điều đó có giống cách mình thường phản ứng trong những tình huống tương tự không?', true, 15),
('UPR_016', '🔍', 'Đâu là những điều thực sự đã diễn ra, và phần nào chỉ là điều mình đang suy diễn?', true, 16)
insert into public.care_actions (care_action_id, care_group, emoji, title_vn, description_vn, duration_min, active, sort_order)
values
('CARE_001', 'grounding', '👀', 'Gọi tên 5 món đồ quanh mình', 'Nhìn quanh và chọn năm món đồ đang ở gần. Gọi tên hoặc miêu tả nhanh màu sắc, hình dạng, chất liệu hay một chi tiết mình vừa để ý thấy.', 3, true, 1),
('CARE_002', 'grounding', '🌬️', 'Hít thở và đếm chậm 10 nhịp', 'Thở theo nhịp tự nhiên và đếm chậm từ một đến mười. Không cần cố hít sâu; chỉ cần để việc đếm giúp mình chậm lại một chút.', 2, true, 2),
('CARE_003', 'grounding', '🎨', 'Tìm ba màu quanh mình', 'Quan sát không gian và tìm ba màu khác nhau. Có thể nhìn thêm xem mỗi màu đang xuất hiện ở đâu và màu nào khiến mình chú ý nhất.', 2, true, 3),
('CARE_004', 'reset', '🌤️', 'Bước ra ngoài và hít thở không khí', 'Ra ban công, trước cửa, sân hoặc một khoảng ngoài trời gần nhất. Đứng hoặc đi chậm vài phút, để ý không khí, nhiệt độ và ánh sáng bên ngoài.', 5, true, 4),
('CARE_005', 'reset', '🎧', 'Nghe trọn một bài nhạc mình thích', 'Chọn một bài mình thật sự muốn nghe và nghe từ đầu đến cuối. Trong vài phút đó, không cần vừa nghe vừa lướt thêm thứ khác.', 5, true, 5),
('CARE_006', 'reset', '🚿', 'Tắm và thay đồ thoải mái', 'Tắm theo cách phù hợp với lúc này, rồi thay một bộ đồ sạch và dễ chịu. Mục tiêu đơn giản là để cơ thể thấy thoải mái hơn so với trước đó.', 15, true, 6),
('CARE_007', 'experience', '🍲', 'Thưởng cho mình một bữa ăn ngon', 'Chọn một món mình thật sự muốn ăn, trong phạm vi thời gian và chi phí phù hợp. Dành cho bữa ăn một khoảng riêng thay vì vừa ăn vừa tiếp tục làm việc.', 30, true, 7),
('CARE_008', 'connection', '🌙', 'Hẹn một cuộc gọi buổi tối', 'Nghĩ đến một người mình muốn nghe giọng và gửi một lời hẹn cụ thể. Cuộc gọi có thể để tâm sự, cập nhật cuộc sống hoặc đơn giản là trò chuyện linh tinh.', 30, true, 8),
('CARE_009', 'connection', '☕', 'Hẹn một buổi cà phê hoặc nhâm nhi cùng bạn bè', 'Chọn một hoặc vài người mình muốn gặp và đề xuất thời gian, địa điểm cụ thể. Có thể là cà phê, trà, ăn vặt hoặc một buổi ngồi cùng nhau không cần kế hoạch lớn.', 60, true, 9),
('CARE_010', 'connection', '💬', 'Nhắn cho một người mình muốn kết nối cùng', 'Gửi một tin nhắn để chia sẻ điều đang nghĩ, một chuyện vừa xảy ra hoặc chỉ để hỏi xem người đó dạo này thế nào. Không cần đợi đến khi có một câu chuyện thật quan trọng.', 5, true, 10),
('CARE_011', 'connection', '🙏', 'Gửi một lời cảm ơn thật cụ thể', 'Nghĩ đến một người đã làm điều gì đó có ý nghĩa với mình. Nói rõ mình cảm ơn việc gì và điều đó đã ảnh hưởng đến mình ra sao.', 5, true, 11),
('CARE_012', 'connection', '🤍', 'Ở gần một người mình thấy an toàn', 'Dành một khoảng thời gian ở cạnh người khiến mình không phải cố gắng thể hiện gì. Có thể trò chuyện, cùng ăn, xem gì đó hoặc mỗi người làm việc riêng.', 30, true, 12),
('CARE_013', 'experience', '🎭', 'Đi xem một màn trình diễn nghệ thuật', 'Tìm một buổi hài, kịch, xiếc, hòa nhạc, múa, triển lãm hoặc loại hình biểu diễn khiến mình tò mò. Có thể đi ngay hoặc đặt lịch cho một ngày gần nhất.', 90, true, 13),
('CARE_014', 'experience', '👐', 'Làm một việc gì đó bằng tay', 'Nấu một món nhỏ, chăm cây, tô màu, xếp đồ, gấp giấy, đan móc hoặc lắp ráp thứ gì đó. Chọn việc cho đôi tay được bận mà không cần tạo ra sản phẩm hoàn hảo.', 15, true, 14),
('CARE_015', 'experience', '🗺️', 'Đổi một chi tiết quen thuộc trong ngày', 'Thử đổi đường đi, chỗ ngồi, món uống, playlist hoặc nơi mình làm việc. Chỉ cần một thay đổi nhỏ để hôm nay không hoàn toàn giống mọi ngày.', 10, true, 15),
('CARE_016', 'expression', '✍️', 'Viết tự do trong vài phút', 'Viết liên tục bất cứ điều gì đang xuất hiện. Không sửa câu, không cần đúng ngữ pháp, không cần hợp lý và cũng chưa cần đi đến kết luận.', 5, true, 16),
('CARE_017', 'expression', '🌟', 'Ghi nhận bản thân một điều bất kỳ', 'Ghi lại một điều mình muốn công nhận ở bản thân hôm nay. Có thể là một nỗ lực, một lựa chọn, một việc đã hoàn thành hoặc cách mình đã đi qua một tình huống.', 3, true, 17),
('CARE_018', 'expression', '✉️', 'Viết một lời gửi cho mình trong tương lai', 'Chọn một thời điểm trong tương lai — vài ngày, vài tháng hoặc một năm nữa — rồi viết vài dòng về điều đang diễn ra và điều mình muốn bản thân khi ấy nhớ lại.', 10, true, 18),
('CARE_019', 'expression', '📷', 'Lưu lại một hình ảnh của hôm nay', 'Chụp một chi tiết đại diện cho hôm nay: bầu trời, góc phòng, món ăn, ánh sáng hoặc một khoảnh khắc rất bình thường. Có thể thêm một câu để nhớ vì sao mình chọn hình đó.', 5, true, 19),
('CARE_020', 'clarity', '🧭', 'Chọn cho mình một tâm thế mới', 'Chọn một từ cho phần còn lại của ngày, chẳng hạn bình tĩnh, tò mò, dứt khoát, cởi mở hoặc chậm lại. Sau đó chọn một việc nhỏ phù hợp với tâm thế đó.', 3, true, 20),
('CARE_021', 'clarity', '🔍', 'Tách điều đã xảy ra khỏi điều mình suy diễn', 'Viết hai phần: điều mình biết chắc đã xảy ra và điều mình đang nghĩ rằng nó có nghĩa là gì. Không cần loại bỏ suy nghĩ, chỉ cần nhìn rõ hai phần đang khác nhau ở đâu.', 7, true, 21),
('CARE_022', 'clarity', '🪶', 'Bỏ bớt một việc khỏi hôm nay', 'Chọn một việc có thể hoãn, thu nhỏ, nhờ người khác hỗ trợ hoặc bỏ hẳn. Ưu tiên việc đang chiếm nhiều sức hơn giá trị mà nó mang lại trong hôm nay.', 5, true, 22),
('CARE_023', 'rest', '🛏️', 'Chuẩn bị chỗ ngủ dễ chịu hơn', 'Chỉnh lại chăn, gối, ánh sáng, nhiệt độ hoặc dọn những thứ đang nằm trên giường. Mục tiêu là để khi muốn nghỉ, mình có thể nằm xuống ngay mà không phải chuẩn bị thêm.', 10, true, 23),
('CARE_024', 'rest', '📵', 'Cho mình một buổi tối không thông báo', 'Chọn một khoảng trong buổi tối để tắt thông báo và không trả lời những tin nhắn mình chưa muốn trả lời. Những việc thật sự cần thiết có thể được xử lý trước hoặc để lại một mốc phản hồi rõ ràng.', 60, true, 24),
('CARE_025', 'rest', '📖', 'Đọc vài trang sách hoặc truyện mình thích', 'Chọn một cuốn sách hoặc truyện mình thật sự muốn đọc. Đọc vài trang theo nhịp của mình, không cần đạt số trang hay biến nó thành một mục tiêu phải hoàn thành.', 15, true, 25),
('CARE_026', 'memory', '🧸', 'Xem lại những món đồ kỷ niệm ngày trước', 'Mở lại một chiếc hộp, món đồ, tấm vé, bức thư hoặc vật nhỏ gắn với một khoảng thời gian trước đây. Chọn một vài món để xem rồi cất lại khi thấy vừa đủ.', 15, true, 26)
